2	
3	const MAX_CONTENT_LENGTH = 10000;
4	
5	interface ValidationSuccess {
6	  valid: true;
7	  data: IncomingMessage;
8	}
9	
10	interface ValidationFailure {
11	  valid: false;
12	  error: string;
13	}
14	
15	export type ValidationResult = ValidationSuccess | ValidationFailure;
16	
17	export function validateMessage(payload: unknown): ValidationResult {
18	  if (typeof payload !== 'object' || payload === null) {
19	    return {valid: false, error: 'Message must be an object'};
20	  }
21	
22	  const message = payload as Record<string, unknown>;
23	
24	  if (typeof message.type !== 'string') {
25	    return {valid: false, error: 'Message must have a type field'};
26	  }
27	
28	  const validate = VALIDATORS.get(message.type);
29	  if (validate === undefined) {
30	    return {valid: false, error: `Unknown message type: ${message.type}`};
31	  }
32	  return validate(message);
33	}
34	
35	type FrameValidator = (message: Record<string, unknown>) => ValidationResult;
36	
37	const VALIDATORS = new Map<string, FrameValidator>([
38	  ['user_message', validateUserMessage],
39	  ['ping', validatePingMessage],
40	  ['list_sessions', validateListSessionsMessage],
41	]);
42	
43	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
44	  if (typeof message.content !== 'string') {
45	    return {valid: false, error: 'user_message must have content string'};
46	  }
47	
48	  const trimmed = message.content.trim();
49	
50	  if (trimmed.length === 0) {
51	    return {valid: false, error: 'Message content cannot be empty'};
52	  }
53	
54	  if (message.content.length > MAX_CONTENT_LENGTH) {
55	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
56	  }
57	
58	  return {
59	    valid: true,
60	    data: {
61	      type: 'user_message',
62	      content: message.content,
63	    },
64	  };
65	}
66	
67	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
68	  if (message.limit !== undefined && (!Number.isInteger(message.limit) || (message.limit as number) < 0)) {
69	    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
70	  }
71	
72	  if (message.before !== undefined && (typeof message.before !== 'object' || message.before === null)) {
73	    return {valid: false, error: 'list_sessions before must be a cursor object'};
74	  }
75	
